package io.github.supermonster003.autojs6.plugin.bundled.libraries

import java.util.Locale

/**
 * The bundled changelog (`assets/doc/CHANGELOG-<tag>.md`, generated by `.python/generate_markdown.py`): which file a
 * locale reads, and the lines of the fixed layout the generator writes. Kept free of Android types for the JVM tests.
 * zh-CN: 内置的更新日志 (`assets/doc/CHANGELOG-<tag>.md`, 由 `.python/generate_markdown.py` 生成): 各语言读取哪个文件,
 * 以及生成器固定格式的各行. 不依赖 Android 类型, 便于 JVM 测试.
 */
internal object ReleaseHistory {

    enum class Kind { VERSION, DATE, ITEM, TEXT }

    data class Line(val kind: Kind, val text: String, val label: String? = null)

    /** Asset paths to try for [locale], the English one last but one, the default (Simplified Chinese) copy last. */
    fun candidates(locale: Locale): List<String> {
        val language = locale.language.lowercase(Locale.ROOT)
        val region = locale.country.uppercase(Locale.ROOT)
        val primary = when (language) {
            "zh" -> when {
                region == "HK" || region == "MO" -> "zh-Hant-HK"
                locale.script == "Hant" || region == "TW" -> "zh-Hant-TW"
                else -> "zh-Hans"
            }
            "ar", "en", "es", "fr", "ja", "ko", "ru" -> language
            else -> null
        }
        return listOfNotNull(primary, "en").distinct().map { "doc/CHANGELOG-$it.md" } + "doc/CHANGELOG.md"
    }

    /**
     * The release lines of [markdown]: `# vX.Y.Z`, `###### YYYY/MM/DD` and "* `Label` text" items; the title, the
     * separators and blank lines are dropped.
     */
    fun parse(markdown: String): List<Line> = markdown.lineSequence().map(String::trim).mapNotNull { line ->
        when {
            line.isEmpty() || line.all { it == '*' } || line.startsWith("### ") -> null
            line.startsWith("###### ") -> Line(Kind.DATE, line.removePrefix("###### ").trim())
            line.startsWith("# ") -> Line(Kind.VERSION, line.removePrefix("# ").trim())
            line.startsWith("* ") -> ITEM.matchEntire(line)?.let { Line(Kind.ITEM, it.groupValues[2], it.groupValues[1]) }
                ?: Line(Kind.ITEM, line.removePrefix("* "))
            else -> Line(Kind.TEXT, line)
        }
    }.toList()

    private val ITEM = Regex("""^\* `([^`]+)` (.+)$""")

}
